import os
from datetime import datetime, timedelta, timezone
from typing import Dict, Iterable, List, Optional

from google.cloud import monitoring_v3
from google.protobuf import duration_pb2, timestamp_pb2


class GCPMetricsMonitor:
    def __init__(self, project_id: Optional[str] = None) -> None:
        self.project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT")
        if not self.project_id:
            raise ValueError("project_id is required or set GOOGLE_CLOUD_PROJECT")
        self.client = monitoring_v3.MetricServiceClient()
        self.project_name = f"projects/{self.project_id}"

    def query_time_series(
        self,
        metric_type: str,
        resource_type: str,
        minutes: int = 10,
        resource_labels: Optional[Dict[str, str]] = None,
        metric_labels: Optional[Dict[str, str]] = None,
        alignment_period_seconds: int = 60,
        per_series_aligner: monitoring_v3.Aggregation.Aligner = monitoring_v3.Aggregation.Aligner.ALIGN_MEAN,
        cross_series_reducer: monitoring_v3.Aggregation.Reducer = monitoring_v3.Aggregation.Reducer.REDUCE_NONE,
        group_by_fields: Optional[Iterable[str]] = None,
    ) -> List[Dict]:
        end = datetime.now(timezone.utc)
        start = end - timedelta(minutes=minutes)

        interval = monitoring_v3.TimeInterval(
            {
                "end_time": self._to_timestamp(end),
                "start_time": self._to_timestamp(start),
            }
        )

        filter_parts = [
            f'metric.type = "{metric_type}"',
            f'resource.type = "{resource_type}"',
        ]

        if resource_labels:
            for key, value in resource_labels.items():
                filter_parts.append(f'resource.labels.{key} = "{value}"')

        if metric_labels:
            for key, value in metric_labels.items():
                filter_parts.append(f'metric.labels.{key} = "{value}"')

        aggregation = monitoring_v3.Aggregation(
            alignment_period=duration_pb2.Duration(seconds=alignment_period_seconds),
            per_series_aligner=per_series_aligner,
            cross_series_reducer=cross_series_reducer,
            group_by_fields=list(group_by_fields or []),
        )

        results = self.client.list_time_series(
            request={
                "name": self.project_name,
                "filter": " AND ".join(filter_parts),
                "interval": interval,
                "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
                "aggregation": aggregation,
            }
        )

        output: List[Dict] = []
        for series in results:
            output.append(
                {
                    "metric_type": series.metric.type,
                    "metric_labels": dict(series.metric.labels),
                    "resource_type": series.resource.type,
                    "resource_labels": dict(series.resource.labels),
                    "points": [self._point_to_dict(point) for point in series.points],
                }
            )
        return output

    def _to_timestamp(self, dt: datetime) -> timestamp_pb2.Timestamp:
        ts = timestamp_pb2.Timestamp()
        ts.FromDatetime(dt)
        return ts

    def _point_to_dict(self, point) -> Dict:
        value = point.value
        typed_value = None

        if value.bool_value is not None:
            typed_value = value.bool_value
        if value.int64_value:
            typed_value = value.int64_value
        if value.double_value:
            typed_value = value.double_value
        if value.string_value:
            typed_value = value.string_value
        if value.distribution_value and value.distribution_value.count is not None:
            typed_value = {
                "count": value.distribution_value.count,
                "mean": value.distribution_value.mean,
                "sum_of_squared_deviation": value.distribution_value.sum_of_squared_deviation,
            }

        return {
            "interval_start": point.interval.start_time.isoformat() if point.interval.start_time else None,
            "interval_end": point.interval.end_time.isoformat() if point.interval.end_time else None,
            "value": typed_value,
        }
